{"packet_id":"D070-04","doc_id":"D070","jurisdiction":"Newark, NJ","category":"rent_increase_limits","lifecycle":"enacted","title":"Newark substantially rehabilitated vacant unit 10% rent increase limit","requirement":"A landlord that rehabilitates a vacant apartment unit by spending at least 12 months of the unit's actual monthly rent may raise the rent by no more than 10%. The increase must be applied for with a supporting affidavit before the Board.","key_value":"10% increase","coverage_conditions":"Any landlord that rehabilitates a vacant apartment unit by spending a total amount equal to at least 12 months of actual monthly rent per unit.","applicability":{"conditions":[],"per_tenancy":"Applies where a landlord rehabilitates a vacant apartment unit spending at least 12 months of actual monthly rent per unit.","coverage_quotes":[]},"exemptions":null,"penalty":"Violation of the chapter is punishable by a fine of not less than $100 and not more than $2,000, or imprisonment up to 90 days, or both; the Municipal Court may impose up to $2,000 per violation.","effective_date":"2024-09-18","valid_through":null,"citation":"Newark, NJ Mun. Code § 19:2-18.4","quoted_span":"Any landlord that rehabilitates a vacant apartment unit by spending a total amount equal to at least 12 months of actual monthly rent per unit will be entitled to a maximum of 10% increase in the actual monthly rent.","interaction":null,"relations":[],"confidence":0.9,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D070-04","doc_id":"D070","jurisdiction":"Newark, NJ","category":"rent_increase_limits","lifecycle":"enacted","title":"Newark 25% annual rent increase limit","requirement":"The Rent Control Board may not grant a rent increase exceeding 25% in any one year for any tenant. Increases under the rent increase, major improvement and landlord hardship sections within the prior 12 months are added together to test the 25% limit.","key_value":"25% in any one year","coverage_conditions":"Any tenant; applies to increases granted by the Rent Control Board under the rent control ordinance.","applicability":{"conditions":[],"per_tenancy":"Applies to any tenant; covers rent increases granted by the Rent Control Board.","coverage_quotes":[]},"exemptions":null,"penalty":"Violation of the chapter is punishable by a fine of not less than $100 and not more than $2,000, or imprisonment up to 90 days, or both; the Municipal Court may impose up to $2,000 per violation.","effective_date":"2024-09-18","valid_through":null,"citation":"Newark, NJ Mun. Code § 19:2-22","quoted_span":"Since an immediate rent increase of more than 25% above the prior monthly rent may be considered unconscionable and imposes a hardship on a tenant, the Rent Control Board shall not grant increases exceeding 25% in any one year for any tenant.","interaction":null,"relations":[],"confidence":0.9,"conflict_flag":false,"conflict_note":null}
